'use strict';
const ASSETS={};
function asset(path){return ASSETS[path]||path+'?v=xiaohe-20260917';}
const titles=['同一件事，不同感觉','发现情绪的信号','想法怎么影响我','调节有不同入口','给自己一点缓冲','选一个小行动','一起练习一次','有人可以陪你','带走一个方法'];
const durations=[5,5,5,4,7,6,4,9,5], starts=[0,5,10,15,19,26,32,36,45];
const state={feeling:null,signal:0,path:0,fact:null,strategy:2,method:0,action:0,support:0,recap:null};
let phase=-1,motion=true,theoryPage=0;
let step=0,timer=null,remaining=60,total=60,running=false,voice=false,lastPrompt='';
const $=s=>document.querySelector(s);
function audioPlayer(name,label){return `<div class="local-audio"><span>${label}</span><audio controls preload="metadata" src="${asset('media/'+name+'.mp3')}" aria-label="${label}"></audio></div>`}
const feelingResponses=['期待可能与喜欢分享、想试一试有关。别人担心，也同样说得通。','紧张可能与不熟悉、在意表现有关。我们可以先看见它，再决定需要什么。','期待和紧张可以一起出现。一个人的感受也可以很丰富。','说不清也没关系。可以从“我有点不舒服”或身体的感觉开始。'];
const strategies=[['选择情境','情境选择','选个合适的地方再谈','和朋友意见不同时，可以约在安静、双方都方便的时候聊。'],['改变情境','情境修正','请人一起处理实际困难','发生冲突时，可以请老师协助。困难的环境也需要改变。'],['调整注意','注意分配','把注意放回眼前','留意笔的颜色和边缘。分心后，愿意再看回来，也是在练习。'],['重新理解','认知改变','给尚未确认的原因留一点空间','“我还不知道他为什么没回应。可以找机会了解，也可以请人帮忙。”'],['调节反应','反应调节','给身体一些缓冲','坐得舒服些，按自己的节奏自然呼吸。不用憋气，也不用强行深呼吸。']];
function eyebrow(label){return `<div class="eyebrow">${label}<span class="time">${starts[step]}—${starts[step]+durations[step]} 分钟</span></div>`}
function heading(title,intro,tag=''){return `<div class="stage-heading"><div><h1>${title}</h1>${intro?`<p class="intro">${intro}</p>`:''}</div>${tag?`<span class="theory-tag">${tag}</span>`:''}</div>`}
function choice(label,id,i,selected){return `<button class="option ${selected===i?'selected':''}" data-${id}="${i}" aria-pressed="${selected===i}"><b>${i+1}</b>${label}</button>`}
function first(){return `${eyebrow('互动 01 / 你的感觉有自己的理由')}<div class="split"><section><h1>同一件事，<br>感觉会一样吗？</h1><div class="visual postcard"><img src="${asset('assets/thinking.webp')}" alt="一位学生坐在书桌前思考，头顶有象征纷乱想法的线团"><span class="sticker">没有标准答案</span></div></section><section><p class="intro">想象一下，老师突然宣布：</p><p class="question">“明天，每个人上台<br>讲一分钟。”</p><p>听到这里，你可能有什么感觉？</p>${audioPlayer("feeling","听一听这个情境")}<div class="options">${['有点期待','有点紧张','两种都有','还说不清'].map((x,i)=>choice(x,'feeling',i,state.feeling)).join('')}</div><div class="response" id="feelingResponse" aria-live="polite">${state.feeling===null?'先在心里选一个，或点选看看。<br>也可以暂时旁观。':feelingResponses[state.feeling]}</div><details class="agreement"><summary>我们的小约定</summary><p>只用虚构故事，不必说自己的难过经历。可以参与，也可以旁观。不起哄、不追问。涉及安全时，老师会联系能够帮助你的大人。</p></details></section></div>`}
function signals(){const content=[['身体','肩膀紧、心跳快，或有点想哭。','同一个身体信号可能有不同原因，不能用一个信号判断一种情绪。'],['脑中的话','“要是忘词了，怎么办？”','我们对事情的理解，与感受、身体反应和行为互相影响。'],['想做的事','想把本子合上，或想找人陪。','情绪会带来行动倾向，但我们仍可以在支持下选择怎样做。']];return `${eyebrow('认识情绪 / 先发现，不急着评价')}${heading('情绪来了，会留下什么信号？','小宁明天要做课堂展示。看看他可能正在经历什么。','情绪与相关反应')}<div class="lab-layout"><div class="visual"><img src="${asset('assets/thinking.webp')}" alt="小宁坐在书桌前，正在思考明天的展示"></div><section><div class="lab-tabs">${content.map((a,i)=>`<button class="lab-tab ${state.signal===i?'active':''}" data-signal="${i}" aria-pressed="${state.signal===i}"><strong>${a[0]}</strong><span>${a[1]}</span></button>`).join('')}</div><div class="response" id="signalResponse" aria-live="polite">${content[state.signal][2]}</div><div class="concept"><b>感受与行为，可以分开看。</b><br>“我很生气”可以被理解。表达时，也可以保护自己和别人。情绪有时提示我们在意什么，不必为每次难过找一个理由。</div></section></div>`}
function thoughts(){const p=state.path===0?['“他是不是讨厌我？”','担心、委屈<br>肩膀有点紧','不再打招呼<br>也暂时不去问']:['“原因还不清楚，<br>可以再了解。”','仍有些担心<br>也可能多一点余地','找机会问一问<br>或请老师协助'];return `${eyebrow('互动 02 / 发生的事与想到的原因')}${heading('脑中的解释，会影响下一步。','对照两种理解，看看可能出现的不同路径。','认知行为模型 · 课堂简化')}<div class="scenario">你向朋友打招呼，对方暂时没有回应。</div><div class="switches"><button data-path="0" class="${state.path===0?'active':''}" aria-pressed="${state.path===0}">解释一：他是不是讨厌我？</button><button data-path="1" class="${state.path===1?'active':''}" aria-pressed="${state.path===1}">解释二：原因还不清楚</button></div><div class="model" aria-live="polite">${p.map((x,i)=>`${i?'<div class="model-join" aria-hidden="true">↔</div>':''}<div class="model-part"><h3>${['想法','感受与身体','行为'][i]}</h3><p>${x}</p></div>`).join('')}</div><p class="fine">这些部分相互影响。现实处境、关系与身体状态也很重要；核实原因不等于否定感受。</p><section class="check-panel"><div><h2>换个故事，试着辨认</h2><p>回答问题后，后排有人笑了。<br>哪句话描述了观察到的事情？</p>${audioPlayer("fact","听一听活动问题")}</div><div class="options">${['后排有人笑了','他们肯定在笑我'].map((x,i)=>choice(x,'fact',i,state.fact)).join('')}</div>${state.fact!==null?`<div class="response" aria-live="polite">${state.fact===0?'这句话描述了观察。笑的原因，还需要了解。':'这句话是在推断笑的原因。感到受伤是真的，但原因还可以进一步了解。'} 感到受伤就可以求助，不需要先证明对方是故意的。</div>`:''}</section>`}
function regulation(){const a=strategies[state.strategy];return `${eyebrow('理解方法 / 找一个合适的入口')}${heading('调节情绪，有不止一种办法。','不必等到特别难受时才行动，也不用把每个方法都做一遍。','Gross 情绪调节过程模型')}<div class="strategy-nav">${strategies.map((a,i)=>`<button data-strategy="${i}" class="${state.strategy===i?'active':''}" aria-pressed="${state.strategy===i}"><strong>0${i+1}</strong><span>${a[0]}</span><small>${a[1]}</small></button>`).join('')}</div><div class="strategy-detail" aria-live="polite"><div class="big-num">0${state.strategy+1}</div><section><h2>${a[2]}</h2><p>${a[3]}</p></section></div><div class="concept"><b>看见感受，缓一缓，再选一步。</b><br>这三句话是今天的记忆口诀。五类策略帮助理解“可以从哪里入手”，不要求按顺序完成。</div><p class="small-note">遇到伤害或威胁，先到安全处、找可信任的大人。暂时缓冲后，也可以回来处理实际问题。</p>`}
function timeText(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function timerPanel(kind){return `<section class="practice-panel" data-timer-kind="${kind}"><span class="badge">${kind==='ground'?'跟着自己的节奏':'两个人，或自己也可以'}</span><div class="timer-face"><strong id="clock">${timeText(remaining)}</strong><span>${kind==='ground'?'一轮观察练习':'演练与反馈'}</span></div><div id="timerPrompt" class="timer-prompt" aria-live="polite">${promptNow(kind)}</div><div class="timer-buttons"><button class="primary" id="timerToggle">${running?'暂停练习':remaining===0?'再试一轮':'开始练习'}</button><button id="timerReset">重新计时</button></div>${kind==='ground'?`<button class="voice-start" id="startVoiced">▶ 开始有声练习</button><label class="voice-control"><input id="voice" type="checkbox" ${voice?'checked':''}>播放语音引导</label><audio id="guideAudio" preload="metadata" src="${asset('media/'+(state.method===0?'observe':'support')+'.mp3')}"></audio><p class="fine" id="voiceStatus"></p>`:''}<p class="fine">随时可以暂停或旁观，不需要坚持到结束。</p></section>`}
function grounding(){return `${eyebrow('互动 03 / 给自己一点缓冲')}${heading('先不急，和眼前的世界待一会儿。','我们练习调整注意，给下一步留出空间。感受不一定马上改变。')}<div class="timer-layout">${timerPanel('ground')}<section class="practice-guide"><img src="${asset('assets/observe.webp')}" alt="学生睁着眼睛，观察手中的铅笔"><div class="chips"><button data-method="0" class="${state.method===0?'active':''}" aria-pressed="${state.method===0}">观察一件物品</button><button data-method="1" class="${state.method===1?'active':''}" aria-pressed="${state.method===1}">留意身体支撑</button></div><h2>${state.method===0?'把注意放在颜色和形状上':'感受椅子或地面对身体的支撑'}</h2><p>可以睁眼，按自己的节奏自然呼吸。分心很正常，愿意时再把注意带回来。不舒服就停下来，找老师陪。</p><div class="mini-feedback"><strong>练习之后，想一想</strong><br>刚才，我把注意力放在了哪里？<br>不用比较谁更放松。</div><p class="fine">本轮 60 秒。提示之间留有安静练习时间。中文合成旁白，文字与语音内容一致。</p></section></div>`}
const actionData=[['“我有点失望，<br>但一次结果不能概括我。”','先圈出一个不懂的地方，再请人一起看看。也可以先休息一下。','一次没有做好，也可能与方法、任务难度或身体状态有关。'],['“下一次，<br>你希望我具体怎么做？”','等能说话时，确认对方说的是哪一件事。需要时请另一位可信任的大人陪同。','不必先完全平静，才有资格表达自己的需要。'],['“这件事让我不舒服，<br>我想请你帮忙。”','先保护自己，找可信任的老师或其他大人。第一位没认真回应，可以再找一位。','持续羞辱、威胁或欺凌，需要成人协助处理，不要求自己独自沟通解决。']];
function action(){const a=actionData[state.action];return `${eyebrow('把方法变成行动 / 具体一点就更容易开始')}${heading('下一句话，你可以这样说。','有时候需要调整想法，有时候需要休息，也有时候需要环境改变。')}<div class="action-layout"><div class="scene-tabs">${['事情没有做好','收到具体提醒','遇到羞辱或威胁'].map((x,i)=>`<button data-action="${i}" class="${state.action===i?'active':''}" aria-pressed="${state.action===i}">${x}</button>`).join('')}</div><section class="action-card" aria-live="polite"><span class="label">一个可以试用的说法</span><div class="quote">${a[0]}</div><p>${a[1]}</p></section></div><div class="concept">${a[2]}</div><p class="small-note">把“我要变好”缩小成眼前的一步，例如“圈出一道题”“确认一句话”或“去找一个人”。</p>`}
function rehearsal(){return `${eyebrow('互动 04 / 说出来，也试着做一次')}${heading('替小安练一次。','小安作业遇到难题，心想：“我太差了，不想做了。”')}<div class="rehearsal"><section class="prompt-card"><span class="label">用这个开头，也可以换成自己的说法</span><div class="big-quote">“我有点……<br>我先……”</div>${audioPlayer("pair","听一听演练说明")}<div class="phase-list"><div><strong>先想一想</strong>一句话、一个小动作</div><div><strong>轮流练习</strong>同桌各说一次，另一人复述</div><div><strong>一起检查</strong>这一步具体、安全、能做到吗？</div></div><p class="fine" style="margin-top:20px">只用虚构故事，不演强烈情绪。不愿开口，可以默想或写下来。</p></section>${timerPanel('pair')}</div>`}
const supportAnswers=['“听起来，你真的挺难受。<br>你希望我听你说，还是一起想办法？”','“想说的时候，我在。<br>如果你愿意，我们也可以找老师。”','“我很关心你。<br>这件事我们需要找能帮助你的大人。”'];
function support(){return `${eyebrow('陪伴与求助 / 有些事，可以一起处理')}${heading('朋友难过时，你可以怎样回应？','先听见感受，再问需要。朋友不必独自承担所有问题。')}<div class="support-grid"><div><img src="${asset('assets/friends.webp')}" alt="两位同龄学生面对面坐着，一位说话，另一位认真倾听"><details class="local-video"><summary>看一个同伴支持小故事 · 45 秒</summary><video controls playsinline preload="metadata" poster="${asset('assets/friends.webp')}" src="${asset('media/friend-story.mp4')}" aria-label="同伴支持教学短片，45秒，含中文旁白与画面文字">当前浏览器无法播放视频，请阅读右侧的完整说法。</video><p class="fine">原创教学短片，中文合成旁白。画面已带文字，可静音观看。</p></details></div><section><div class="response-choices">${['对方愿意说，但还没想好要什么','对方现在不想分享','对方提到正在被伤害或想伤害自己'].map((x,i)=>`<button data-support="${i}" class="${state.support===i?'active':''}" aria-pressed="${state.support===i}">${x}</button>`).join('')}</div><div class="response" aria-live="polite">${supportAnswers[state.support]}${state.support===2?'<br><strong>尽快告诉可信任的大人，不承诺替对方保守安全风险的秘密。</strong>':''}</div></section></div><section class="help-path"><h2>我需要帮助时，也可以早点说。</h2><div class="help-cards"><article class="help-card"><h3>想有人陪</h3><p>困扰还不严重，也可以求助。不必先把所有事情理清楚。</p></article><article class="help-card"><h3>持续影响生活</h3><p>睡觉、吃饭、上课或交往受到影响，找大人或专业人员一起想办法。</p></article><article class="help-card"><h3>涉及安全</h3><p>正在被伤害，或有伤害自己、他人的念头，马上找身边可信任的大人。</p></article></div><div class="help-script">“我最近有点难受，已经影响到……<br>我想请你陪我一起想办法。”</div><p class="small-note">可以说，也可以写。眼前有危险时，直接去找能帮助你的大人，不要只发消息后独自等待。</p></section>`}
const recapOptions=['看看眼前的物品','请信任的人陪一会儿','先做一件很小的事'];
function ending(){return `${eyebrow('带回生活 / 不用一次做到完美')}${heading('离开前，给自己留一个办法。','明天要小测，小宁紧张得坐不住。你会建议他先做什么？')}<div class="recap-grid"><section><div class="response-choices">${recapOptions.map((x,i)=>`<button data-recap="${i}" class="${state.recap===i?'active':''}" aria-pressed="${state.recap===i}">${x}</button>`).join('')}</div><div class="response" aria-live="polite">${state.recap===null?'这些都可能是合适的选择，也可以有自己的办法。选一种，再说出具体的第一步。':['可以具体到：看一看笔帽的颜色和形状。紧张没消失，也可以继续找支持。','可以具体到：去找班主任说“我有点紧张，想请你陪我想一想”。','可以具体到：圈出最想问的一道题，再请教老师。不需要一下解决全部困难。'][state.recap]}</div><p class="end-note">试了没有变化，可以换一种、休息一下，或寻求更多帮助。</p></section><section class="takeaway"><span class="small">今天可以带走的三句话</span><h2>看见感受<br>缓一缓<br>再选一步</h2><p>${state.recap===null?'我可以给自己一点时间，也可以想到一个愿意陪我的人。':'下次我可以先试试：<br>'+recapOptions[state.recap]}</p><span class="badge">猜测可以核实</span><span class="badge">困难可以求助</span></section></div><details class="sources"><summary>课程依据与延伸阅读（联网阅读）</summary><ul><li><a target="_blank" rel="noopener noreferrer" href="https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/">NHS：想法、感受与行为之间的联系</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://www.psychiatry.wisc.edu/courses/Nitschke/seminar/gross_2002_psychophys.pdf">Gross（2002）：情绪调节过程模型</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://www.who.int/publications/i/item/9789240003927">WHO：Doing What Matters in Times of Stress</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://www.unicef.org/adolescentkit/activity-box/activity/recognizing-emotions">UNICEF：情绪识别活动</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://www.unicef.org/adolescentmentalhealthhub/documents/helping-adolescents-thrive-facilitator-guide">UNICEF：HAT 带领者指南</a>（原模块针对15—19岁，本课重写为初中情境）</li></ul><p class="fine">这是一堂心理科普课，不能替代个别评估或治疗。情境为教学创作，插画为AI生成，音视频为本课原创，练习与短片旁白使用授课者授权音色合成；双人对话使用授课者音色与另一虚拟角色合成音色。页面不要求填写姓名或私人经历，点选结果不上传。</p></details>`}
const courseSources="<details class=\"sources\"><summary>课程依据与延伸阅读（联网阅读）</summary><ul><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/\">NHS：想法、感受与行为之间的联系</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.psychiatry.wisc.edu/courses/Nitschke/seminar/gross_2002_psychophys.pdf\">Gross（2002）：情绪调节过程模型</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.who.int/publications/i/item/9789240003927\">WHO：Doing What Matters in Times of Stress</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.unicef.org/adolescentkit/activity-box/activity/recognizing-emotions\">UNICEF：情绪识别活动</a></li><li><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.unicef.org/adolescentmentalhealthhub/documents/helping-adolescents-thrive-facilitator-guide\">UNICEF：HAT 带领者指南</a>（原模块针对15—19岁，本课重写为初中情境）</li></ul><p class=\"fine\">这是一堂心理科普课，不能替代个别评估或治疗。情境为教学创作，插画为AI生成，音视频为本课原创，练习与短片旁白使用授课者授权音色合成；双人对话使用授课者音色与另一虚拟角色合成音色。页面不要求填写姓名或私人经历，点选结果不上传。</p></details>";
function displayCards(items,cls=''){return `<div class="display-cards ${cls}">${items.map((a,i)=>`<article class="display-card"><span class="label">${a[0]}</span><h2>${a[1]}</h2><p>${a[2]}</p></article>`).join('')}</div>`}
function first(){return `${eyebrow('互动 01 / 心里选、举手或口头回答')}${heading('明天，每个人上台讲一分钟。','同一句话，可能带来哪些不同感受？')}${displayCards([['01','有点期待','可能想分享，也想尝试。'],['02','有点紧张','可能在意表现，担心忘词。'],['03','期待，也紧张','两种感受可以同时出现。'],['04','还说不清','可以先留意身体的感觉。']],'two-col')}${audioPlayer('feeling','可选：播放情境')}<div class="class-takeaway">想一想：不同的人，为什么会有不同感觉？</div><p class="class-note">可以旁观，不必讲私人经历。不起哄、不追问；涉及安全时，老师会找能帮助的大人。</p>`}
function signals(){return `${eyebrow('情境观察 / 三类信号一起看')}${heading('小宁明天要展示，可能有什么信号？','先描述看见的信号，再了解当时的处境。')}${displayCards([['身体','肩膀紧、心跳快','信号有多种可能原因，不能直接判断情绪。'],['脑中的话','“忘词了怎么办？”','理解一件事的方式，会与感受和行为相互影响。'],['行动冲动','想躲开、想找人陪','想做什么，与最后选择做什么，可以不同。']])}<div class="class-takeaway">感受可以被理解；表达时，也要保护自己和别人。</div>`}
function thoughts(){return `${eyebrow('互动 02 / 直接对照两句话')}${heading('“看见的事”和“猜的原因”，分开看。','回答问题后，后排有人笑了。两句话有什么区别？')}${displayCards([['01 · 观察到的事','“后排有人笑了。”','描述听到或看到的事情。笑的原因还没有确认。'],['02 · 对原因的推测','“他们肯定在笑我。”','加入了对别人想法的判断，还需要进一步了解。']],'two-col')}${audioPlayer('fact','可选：播放活动问题')}<div class="class-takeaway">感到受伤是真的；推测的原因，还可以核实。</div><p class="class-note">口头练一句：我观察到……；我猜测……。受到伤害时，可以直接求助。</p>`}
function regulation(){return `${eyebrow('方法地图 / 五类策略直接展示')}${heading('调节可以从哪里开始？','找一个适合当下处境的入口，不必按顺序做完。','Gross 情绪调节过程模型')}${displayCards([['01 · 情境选择','换个时间或地点','双方都方便时，再谈分歧。'],['02 · 情境修正','请人改变困难处境','发生冲突，请老师协助。'],['03 · 注意分配','看回眼前','观察笔的颜色和边缘。'],['04 · 认知改变','核实尚未确认的原因','“还有什么可能？”'],['05 · 反应调节','给身体与表达一些缓冲','自然呼吸，选择安全的表达。']],'strategy-all')}<p class="class-note">遇到伤害或威胁，优先到安全处、找可信任的大人。</p>`}
function action(){return `${eyebrow('情境迁移 / 三种情况直接对照')}${heading('事情不一样，下一步也可以不一样。','请选一个情境，说出具体、安全、现在能做的一步。')}${displayCards([['事情没有做好','“一次结果不能概括我。”','圈出一个不懂的地方，再请人一起看。'],['收到具体提醒','“希望我具体怎么做？”','确认对方说的是哪件事；需要时请大人陪同。'],['遇到羞辱或威胁','“这让我不舒服，请帮帮我。”','先保护自己，找可信任的大人；不独自处理。']])}<div class="class-takeaway">小步骤不是独自硬扛；寻求帮助也是行动。</div>`}
function support(){return `${eyebrow('观看与讨论 / 回应示例直接展示')}${heading('先听见感受，再问对方需要什么。','看短片时，找出“回应感受”和“询问需要”的说法。')}<div class="support-direct"><video controls playsinline preload="metadata" poster="${asset('assets/friends.webp')}" src="${asset('media/friend-story.mp4')}" aria-label="同伴支持教学短片，45秒，中文旁白与画面文字"></video><section>${displayCards([['愿意说','“听起来，你挺难受。”','“要我听一听，还是一起想办法？”'],['暂时不想说','“想说的时候，我在。”','不追问；可以提出陪他找老师。'],['涉及伤害或安全风险','“我们去找能帮忙的大人。”','尽快告诉可信任的大人，不承诺隐瞒风险。']],'support-lines')}</section></div><p class="class-note">短片45秒，含画面文字，可静音观看。朋友可以陪伴，不必独自负责解决全部问题。</p>`}
function ending(){return `${eyebrow('结课练习 / 说出具体的第一步')}${heading('明天小测，小宁紧张得坐不住。','下面三种办法都可能适合。你会建议他具体怎么开始？')}${displayCards([['留意眼前','观察一件物品','看笔帽的颜色和形状，再决定下一步。'],['找人支持','请信任的人陪一会儿','“老师，我有点紧张，想请您陪我想一想。”'],['做一个小动作','先处理一个问题','圈出最想问的一道题，去请教老师。']])}<div class="class-takeaway">没马上好转也没关系。可以换方法、休息或求助。</div>`}

const visualLessons=[
 ['情绪来了，先看见它。','presentation.webp','感受没有标准答案',['感受','身体信号','行动选择'],['可以不同','先留意','再决定'],'同一件事，感觉也可能不同。'],
 ['身体，也会“说话”。','courtyard.webp','先观察，不急着判断',['身体','脑中的话','想做的事'],['肩膀紧','怕忘词','想找人陪'],'一个信号，可能有不同原因。'],
 ['看到的，不等于想到的。','greeting.webp','猜测可以核实',['想法','感受与身体','行为'],['他讨厌我？','有些委屈','不再打招呼'],'三者相互影响；现实处境也很重要。'],
 ['调节，有不同的入口。','notebook.webp','选一个适合的办法',['环境','注意与理解','反应'],['改变处境','核实猜测','安全表达'],'五类策略，不是五个必做步骤。'],
 ['注意跑远了，可以再回来。','window.webp','分心不等于失败',['发现','回来','选择'],['我走神了','看看眼前','再选一步'],'练习留意眼前，不要求立刻放松。'],
 ['先做一小步。','homework.webp','具体一点，更容易开始',['说清问题','缩小一步','找到支持'],['哪一题？','圈出来','问一问'],'行动要具体、安全、现在能开始。'],
 ['把方法，放进故事里。','notebook.webp','替小安练一次',['看见','缓冲','行动'],['我有点急','先停一下','再问一题'],'练虚构故事，也可以默想。'],
 ['陪伴，从听见开始。','library.webp','不急着劝开心',['听见','询问','找支持'],['你挺难受','需要什么？','找可信大人'],'涉及安全风险，尽快找大人。'],
 ['带走一个，你愿意用的办法。','walking.webp','不用一次做到完美',['看见感受','留出空间','选一步'],['我有点……','我先……','需要时找……'],'可以换方法、休息，也可以求助。']
];
const recapVisual=[['感觉不同，也说得通。','<mark class="focus-key focus-blue">同一件事</mark>，<mark class="focus-key focus-orange">每个人的在意</mark>和<mark class="focus-key focus-purple">理解可能不同。</mark>'],['感受 ≠ 行为','生气可以被理解，表达也要保护彼此。'],['观察 ≠ 推测','感受是真的；原因还可以核实。'],['方法，要看情境。','遇到威胁，先安全、再求助。'],['走神了，再回来。','不用比较谁更放松，不舒服可以停。'],['具体 · 安全 · 能开始','把“我要努力”，换成眼前的一小步。'],['“我有点……我先……”','同桌复述，再检查行动是否具体。'],['听一听 · 问需要 · 找支持','涉及伤害或安全风险，马上找可信任的大人。'],['看见感受，选一步。','试过没变化，也可以休息、换方法或求助。']];
function sceneArt(file,caption){return `<figure class="scene-art"><div class="photo-frame"><img src="${asset('assets/'+file)}" alt="${{'presentation.webp':'戴眼镜的短发女生在教室展示','courtyard.webp':'短发男生在校园长椅上留意肩膀感觉','library.webp':'两名女生在图书馆交流','window.webp':'卷发学生在走廊窗边稍作停留','thinking.webp':'学生在书桌前思考，头顶有纷乱线团','greeting.webp':'走廊里一名学生打招呼，另一名暂未回应','notebook.webp':'笔记本上的线团由纠缠变得疏朗','observe.webp':'学生观察手中铅笔的细节','homework.webp':'学生在书桌前遇到学习困难','friends.webp':'两名学生面对面倾听交谈','walking.webp':'三名学生一起走在路上','teacher.webp':'学生与老师面对面交谈'}[file]||'校园情境插画'}"></div><figcaption>${caption}</figcaption><span class="art-spark" aria-hidden="true">✳</span></figure>`}
function theoryView(){const v=visualLessons[step];return `${eyebrow('先理解 / '+titles[step])}<div class="visual-lesson"><section class="visual-copy"><h2 class="model-name">${theoryNames[step]}</h2><h1>${v[0]}</h1><div class="living-model ${step===2?'mutual-model':''}">${v[3].map((x,i)=>`<div class="living-node" style="--i:${i}"><span class="node-dot">${i+1}</span><div><h2>${x}</h2><p>${v[4][i]}</p></div></div>${i<2?`<span class="living-link" aria-hidden="true">${step===2?'↕':'↓'}</span>`:''}`).join('')}</div><p class="visual-bottom">${v[5]}</p></section>${sceneArt(v[1],v[2])}</div>`}
function reviewView(){const v=recapVisual[step];return `${eyebrow('一起回顾 / 这一次，记住什么')}<div class="review-poster"><section><h1>${v[0]}</h1><p>${v[1]}</p><div class="poster-route"><span>看见感受</span><b>→</b><span>留出空间</span><b>→</b><span>选一步</span></div><p class="poster-question">${['为什么会有不同感觉？','生气时，可以怎样安全表达？','你观察到了什么，又猜测了什么？','遇到难题和遇到威胁，方法一样吗？','刚才，你的注意放在哪里？','现在能做的第一步是什么？','这一步具体、安全、能开始吗？','可以向谁求助？','下次遇到……，我愿意先……。'][step]}</p></section>${sceneArt(['window.webp','homework.webp','library.webp','courtyard.webp','notebook.webp','teacher.webp','walking.webp','teacher.webp','walking.webp'][step],step===8?'带回生活里':'停一下，想一想')}</div>${step===8?'<button class="source-toggle" data-sources="true">课程依据与延伸阅读</button><div id="finalSources"></div>':''}`}
function first(){return `${eyebrow('互动 01 / 心里选，或举手')}<div class="visual-lesson activity-hero"><section><h1>同一件事，<br>感觉会一样吗？</h1><p class="story-line">“明天，每人上台讲一分钟。”</p><div class="feeling-bubbles"><div><span class="face">◡</span><b>期待</b></div><div><span class="face">﹏</span><b>紧张</b></div><div><span class="face">≈</span><b>两种都有</b></div><div><span class="face">?</span><b>说不清</b></div></div><p class="visual-bottom">为什么会有不同感觉？</p>${audioPlayer('feeling','听一听 · 20 秒')}<p class="class-note">可以旁观，不必讲私人经历。</p></section>${sceneArt('library.webp','没有标准答案')}</div>`}
function signals(){return `${eyebrow('情境观察 / 看见情绪的线索')}${heading('小宁明天要展示。','你能发现哪几种信号？')}<div class="signal-scene">${sceneArt('presentation.webp','信号，需要结合情境看')}<section class="signal-stack"><article><span class="signal-icon">♡</span><div><h2>身体</h2><p>肩膀紧 · 心跳快</p></div></article><article><span class="signal-icon">…</span><div><h2>脑中的话</h2><p>“忘词怎么办？”</p></div></article><article><span class="signal-icon">↗</span><div><h2>想做的事</h2><p>想躲开 · 想找人陪</p></div></article></section></div><p class="visual-bottom">同一个信号，可能有不同原因。</p>`}
function thoughts(){return `${eyebrow('互动 02 / 对照，不必点选')}${heading('观察和推测，分开看。','<mark class="focus-key focus-blue">回答问题后，后排有人笑了。</mark>')}<div class="detective-layout"><img src="${asset('assets/lens.webp')}" alt="放大镜，象征辨认观察和推测"><div class="fact-pair"><article><span>观察</span><h2>“后排有人笑了。”</h2><p>我看到、听到的事。</p></article><div class="not-equal" aria-hidden="true">≠</div><article><span>推测</span><h2>“他们肯定在笑我。”</h2><p>我对原因的判断。</p></article></div></div><p class="visual-bottom">感受是真的；原因可以核实。受到伤害可以求助。</p>${audioPlayer('fact','听一听 · 22 秒')}`}
function action(){return `${eyebrow('情境迁移 / 选一个具体行动')}${heading('下一步，可以很小。','选一个故事，替主人公说一句话。')}<div class="story-triptych">${[['homework.webp','卡在难题上','圈出一题，再请教。'],['greeting.webp','没听明白提醒','问清楚：具体怎么做？'],['teacher.webp','遇到羞辱或威胁','先保护自己，找大人。']].map(a=>`<article><img src="${asset('assets/'+a[0])}" alt="${a[1]}的校园情境"><span>${a[1]}</span><h2>${a[2]}</h2></article>`).join('')}</div>`}

function grounding(){return `${eyebrow('互动 03 / 60 秒注意练习')}${heading('给自己一点缓冲。','观察眼前，不要求立刻放松。')}<div class="timer-layout compact-practice">${timerPanel('ground')}<section class="practice-guide">${sceneArt('observe.webp','分心了，可以再回来')}<div class="chips"><button data-method="0" class="${state.method===0?'active':''}" aria-pressed="${state.method===0}">观察物品</button><button data-method="1" class="${state.method===1?'active':''}" aria-pressed="${state.method===1}">留意支撑</button></div><h2>${state.method===0?'看颜色 · 形状 · 细节':'感受椅子或地面的支撑'}</h2><p>可以睁眼，自然呼吸。<br>不舒服就停，找老师陪。</p></section></div>`}
function rehearsal(){return `${eyebrow('互动 04 / 同桌练一练')}${heading('小安卡在难题上：“我太差了。”','替他练一句话，再选一个小动作。')}<div class="rehearsal compact-rehearsal"><section class="prompt-card"><div class="big-quote">“我有点……<br>我先……”</div><div class="rehearsal-steps"><span>想一句</span><b>→</b><span>轮流说</span><b>→</b><span>复述</span></div>${audioPlayer('pair','听说明 · 24 秒')}<p class="class-note">具体 · 安全 · 能开始<br>也可以自己默想。</p></section>${timerPanel('pair')}</div>`}
function ending(){return `${eyebrow('结课练习 / 带回生活里')}${heading('明天小测，小宁紧张得坐不住。','给他一个具体的建议。')}<div class="story-triptych">${[['observe.webp','看回眼前','观察笔帽的颜色。'],['teacher.webp','找人支持','请老师陪我想一想。'],['notebook.webp','先做一小步','圈出最想问的一题。']].map(a=>`<article><img src="${asset('assets/'+a[0])}" alt="${a[1]}的示意图"><span>${a[1]}</span><h2>${a[2]}</h2></article>`).join('')}</div><p class="visual-bottom">可以换方法、休息或求助。</p>`}

const courseSections=[{start:0,title:'认识情绪',question:'情绪来了，我怎么发现？',items:['感受可以不同','留意身体和想法'],image:'presentation.webp',minutes:'0—10'}, {start:2,title:'理解情绪',question:'我的解释，怎样影响下一步？',items:['观察与推测','情绪调节的入口'],image:'greeting.webp',minutes:'10—19'},{start:4,title:'练习调节',question:'现在，我能做哪一小步？',items:['60秒注意练习','小行动与同桌演练'],image:'window.webp',minutes:'19—36'},{start:7,title:'支持与求助',question:'什么时候，可以找人一起？',items:['倾听与回应','求助与带回生活'],image:'library.webp',minutes:'36—50'}];
function sectionIndex(){return step<2?0:step<4?1:step<7?2:3}
function sectionBar(){const i=sectionIndex();return `<div class="section-bar"><strong>第 ${i+1} 部分 · ${courseSections[i].title}</strong><span class="page-kind kind-${phase}">${phase===-1?'本部分导览':phase===0?'理论讲解':phase===1?'情境与活动':'回顾与应用'}</span></div>`}
function sectionIntro(){const i=sectionIndex(),s=courseSections[i];return `<div class="section-cover section-${i}"><section><div class="section-number">0${i+1}</div><h1>${s.title}</h1><p>${s.question}</p><div class="section-outline">${s.items.map((x,k)=>`<div><b>${k+1}</b>${x}</div>`).join('')}</div></section>${sceneArt(s.image,'这一部分，我们一起探索')}</div>`}
const theoryNames=['情绪与反应','情绪的信号与功能','认知行为模型','情绪调节过程模型','注意调节','问题解决','技能迁移','社会支持','方法回顾'];
function phaseNav(){return `<nav class="lesson-phases" aria-label="本节课堂步骤">${['理论讲解','情境与活动','回顾与应用'].map((x,i)=>`<button data-phase="${i}" aria-current="${phase===i?'step':'false'}">${x}</button>`).join('')}</nav>`}
function openMap(){$('#mapItems').innerHTML=courseSections.map((s,i)=>`<section class="map-section"><h3><button data-go="${s.start}">0${i+1} · ${s.title}</button></h3>${titles.map((t,n)=>n>=s.start&&n<(courseSections[i+1]?.start??9)?`<button data-go="${n}"><span>${t}</span><small>${starts[n]}—${starts[n]+durations[n]} 分钟</small></button>`:'').join('')}</section>`).join('');$('#mapDialog').showModal()}

const theoryDetails=[
 [{title:'情绪不只是“脑子里的感觉”。',concept:'当一件事对我们有意义时，可能出现一组相互联系的反应。',key:'一组反应',compare:'感受、身体和行动倾向常常一起出现，但不一定完全同步。',example:'明天要展示：心里紧张、手心出汗、想多练一遍。',apply:'把“我不舒服”说得更清楚：我有什么感受？身体怎么了？',image:'presentation.webp',source:'Gross（2002）；UNICEF 情绪识别',notes:'情绪通常涉及主观体验、生理反应和行为倾向，评价过程与这些成分相联系。课堂用“感受—身体—想做什么”帮助识别，并不把一个信号等同于一种情绪。不同人的反应组合可以不同，同一人的情绪也会随情境变化。避免把正常的紧张说成疾病。'}],
 [{title:'不舒服的情绪，也可能带来信息。',concept:'情绪有时提示：我在意什么、遇到了什么变化、可能需要什么。',key:'带来信息',compare:'情绪是需要了解的线索，不是对事实的最终判定，也不是行动命令。',example:'担心：我在意结果；生气：我觉得不公平；难过：我失望或失去了什么。',apply:'先问“发生了什么”，再问“我可能需要什么”。',image:'courtyard.webp',source:'Gross（2002）；UNICEF 情绪识别',notes:'情绪具有适应功能，但具体含义依情境而变。生气不总是界限受侵犯，也可能涉及疲劳、受挫或误解。不要教学生为某一种情绪寻找唯一原因。把情绪视为线索，同时核实现实情况。'},
 {title:'感受的名称和强度，可以分开描述。',concept:'“有点担心”和“非常害怕”，都可以再具体一点。',key:'名称和强度',compare:'强烈的感受不等于必须马上行动；“我生气”不等于“我可以伤人”。',example:'“我有点生气，肩膀绷着。我先离开冲突现场，找老师。”',apply:'用“我有点／比较／很……”描述自己，不比较谁更能忍。',image:'window.webp',source:'UNICEF 情绪识别；Gross（2002）',notes:'词语帮助交流，不是诊断量表。不要要求学生给全班公开报告分数或私人经历。强度会受环境、身体状态等影响。安全表达包括说明需要、暂时离开、寻求成人支持；不要求先完全平静才能求助。'}],
 [{title:'认知行为模型：三个部分相互影响。',concept:'想法、感受与身体、行为会互相影响，可能形成循环。',key:'相互影响',compare:'不是“想法决定一切”。真实处境、人际关系和身体状态也在影响我们。',example:'“他讨厌我” → 委屈 → 不再打招呼 → 更少机会了解原因。',apply:'可以从一个入口尝试改变：核实原因、调整注意，或找人协助。',image:'greeting.webp',source:'NHS 认知行为自助；课堂简化模型',notes:'认知行为模型强调相互作用。例子的箭头用于说明一种可能的维持循环，并非必然因果。我们不是责怪学生“想错了”，更不能把欺凌等真实环境伤害解释成单纯认知问题。实际问题需要实际帮助。'},
 {title:'重新理解，不是强迫自己“想开点”。',concept:'在原因尚未确认时，把一种猜测放回多种可能之中。',key:'多种可能',compare:'“他一定喜欢我”同样未经确认。更稳妥的是：“原因还不清楚。”',example:'他没回应，也许没听见、正着急，也可能有矛盾；需要进一步了解。',apply:'我直接观察到了什么？还有哪些解释？可以怎样安全地核实？',image:'library.webp',source:'NHS 认知行为自助；Gross 认知改变',notes:'认知重评是改变对处境意义的理解，以影响情绪。它不保证消除难过，也不是替伤害行为辩护。核实可以是合适时候询问、请老师协助，不能要求被伤害者独自与对方对质。'}],
 [{title:'情绪调节：改变体验，也调整表达。',concept:'我们可以影响情绪出现的时机、体验的方式，以及怎样表达和行动。',key:'体验与表达',compare:'调节不等于压住表情，也不只是让不舒服的情绪消失。',example:'上台前准备提纲；临时卡住时停一下；遇到困难时请求帮助。',apply:'根据目标和情境选方法：此刻最需要准备、缓冲，还是支持？',image:'notebook.webp',source:'Gross（2002）情绪调节过程模型',notes:'情绪调节可涉及增强、维持或降低情绪，既涉及体验也涉及表达，不能等同于压抑或“情绪稳定”。避免把任何一种策略永久标为好或坏，应考虑处境和目标。'},
 {title:'五类策略，作用在不同的位置。',concept:'环境：选择／改变情境；心理过程：调整注意／重新理解；反应：调整表达。',key:'不同的位置',compare:'这是五类入口，不是必须依次完成的“五步法”。',example:'换时间谈 → 请老师协调 → 看回眼前 → 核实原因 → 安全说出需要。',apply:'困难来自环境时，也要处理环境；遇到威胁，先保护安全。',image:'teacher.webp',source:'Gross（2002）五类情绪调节策略',notes:'情境选择、情境修正、注意分配、认知改变与反应调节，是过程模型中的五类策略。例子并非要求按箭头依次执行。本课重点练习注意分配、理解的调整、小行动与求助，不要求背诵所有术语。'}],
 [{title:'为什么练习把注意带回眼前？',concept:'注意被担心占据时，观察具体物品能提供一个重新定向的着力点。',key:'重新定向',compare:'目标不是清空想法，也不是用观察代替处理困难。',example:'发现又在担心 → 看笔帽的颜色和边缘 → 决定下一小步。',apply:'分心后可以回来；不舒服就停止。练习结束后再处理眼前的事。',image:'observe.webp',source:'WHO 着陆练习；注意调节',notes:'这是课堂简化的注意练习，不是个体治疗。分心很正常，不以即时放松或成绩评价学生。保持自然呼吸、允许睁眼、允许退出。出现不适时由教师陪伴，必要时衔接支持。'}],
 [{title:'问题解决：把困难变得具体。',concept:'从笼统评价自己，转向可以描述、可以尝试处理的一件事。',key:'具体问题',compare:'“我太差了”在评价整个人；“这一题不会”在描述一个困难。',example:'说清卡点 → 选一个小步骤 → 尝试 → 看看是否还需要帮助。',apply:'第一步要具体、安全、能开始；休息或请人帮忙也可以。',image:'homework.webp',source:'NHS 问题解决与行为方法',notes:'小步骤有助于开始尝试，但不保证任务立即完成或情绪立刻改善。困难可能涉及方法、任务要求、支持不足或身体状态。学生不应把所有失败都归因于意志薄弱；必要时改变任务和环境。'}],
 [],
 [{title:'社会支持，有陪伴，也有实际帮助。',concept:'支持可以是理解感受、一起想办法，或连接有能力提供帮助的人。',key:'多种支持',compare:'朋友能陪伴，不必承担治疗责任；安全风险不能只靠同伴保密。',example:'“我愿意听”是陪伴；“一起找老师”是在连接实际帮助。',apply:'困扰影响生活时早点求助；涉及伤害或安全风险，马上找可信任的大人。',image:'library.webp',source:'UNICEF HAT 教学参考；课堂适龄改编',notes:'困扰不严重也可以求助。持续影响睡眠、饮食、学习或交往时，需要成人或专业人员协助；不使用固定天数作为获得帮助的门槛。第一位大人没有回应，可以继续找另一位。即时风险不能仅发一条消息后独自等待。'}],
 []
];
function detailedTheory(){const a=theoryDetails[step][theoryPage-1];return `<section class="theory-deep"><div class="deep-top"><span class="model-name">${theoryNames[step]}</span><span class="theory-count">${theoryPage+1} / ${theoryDetails[step].length+1}</span></div><h1>${a.title}</h1><div class="deep-grid"><section class="deep-content"><article><span class="meaning-label concept-label">核心概念</span><p>${a.concept.replace(a.key,`<mark class="highlight-concept">${a.key}</mark>`)}</p></article><article><span class="meaning-label distinction-label">关键区别</span><p>${markKey(a.compare,"highlight-distinction")}</p></article><article><span class="meaning-label example-label">生活例子</span><p>${a.example}</p></article></section><aside>${sceneArt(a.image,'把理论放进生活')}<div class="apply-box"><strong>怎么用</strong><p>${markKey(a.apply,"highlight-application")}</p></div></aside></div></section>`}
function nextPart(){if(phase===0&&theoryPage<theoryDetails[step].length){theoryPage++;render();$('#main').focus({preventScroll:true});return}if(phase<2)setPhase(phase+1);else go(step===8?0:step+1)}
function previousPart(){if(phase===0&&theoryPage>0){theoryPage--;render();$('#main').focus({preventScroll:true});return}if(phase===1){setPhase(0);theoryPage=theoryDetails[step].length;render();return}if(phase>0||(phase===0&&[0,2,4,7].includes(step)))setPhase(phase-1);else if(step>0){go(step-1);setPhase(2)}}

const revisedTimes=[[3,1,1],[3,1,1],[3,1,1],[3,.5,.5],[2.5,3,1.5],[3,2,1],[.5,3,.5],[3,4,2],[1,1,3]];
let practiceMode=0,gameIndex=0,gameMessage='',cartoonTimer=null,cartoonElapsed=0,cartoonRunning=false;
const seekObjects=[['叶子','M20 49C8 24 28 11 53 11C53 40 40 57 20 49ZM20 49L43 24','#367566'],['书本','M10 14Q22 10 32 17Q43 10 55 14V50Q43 46 32 53Q20 46 10 50ZM32 17V53','#7964a2'],['水杯','M17 17H43V48Q30 59 17 48ZM43 23H50Q59 32 43 38','#bd7544'],['铅笔','M13 48L43 13L53 23L23 57L10 60ZM38 19L48 29','#477a90'],['地球','M56 32A24 24 0 1 1 8 32A24 24 0 1 1 56 32ZM8 32H56M32 8Q10 32 32 56Q54 32 32 8','#658842'],['椅子','M18 10H47V35H18ZM15 35H50V43H15ZM19 43V58M46 43V58','#bc6764']];
const seekOrder=[1,0,3];
function playTabs(){return `<div class="activity-tabs"><button data-practice-mode="0" class="${practiceMode===0?'active':''}">60秒有声练习</button><button data-practice-mode="1" class="${practiceMode===1?'active':''}">视觉观察小游戏</button></div>`}
function seekGame(){const done=gameIndex>=seekOrder.length;return `<section class="seek-game"><div class="seek-instruction"><span class="game-tag">观察练习 · 不计分</span><h2>${done?'观察完成。':`找一找：${seekObjects[seekOrder[gameIndex]][0]}`}</h2><p>${done?'你刚才留意了颜色、形状，还是细节？':'看清形状，再点一下。可以慢慢来。'}</p><div class="game-feedback" aria-live="polite">${gameMessage||'选择一个物品，开始观察。'}</div><button data-game-reset="1">重新观察</button></div><div class="object-board">${seekObjects.map((a,i)=>`<button data-object="${i}" aria-label="${a[0]}" style="--object-color:${a[2]};--delay:${i*.4}s"><svg viewBox="0 0 64 68" aria-hidden="true"><path d="${a[1]}"/></svg><span>${a[0]}</span></button>`).join('')}</div></section><p class="class-note">不用比快。没变放松也没关系；这是观察练习，不是能力测验。</p>`}
function grounding(){return `${heading('给自己一点缓冲。','选择一种练习即可。')}${playTabs()}${practiceMode===1?seekGame():`<div class="timer-layout compact-practice">${timerPanel('ground')}<section class="practice-guide">${sceneArt('observe.webp','分心了，可以再回来')}<div class="chips"><button data-method="0" class="${state.method===0?'active':''}" aria-pressed="${state.method===0}">观察物品</button><button data-method="1" class="${state.method===1?'active':''}" aria-pressed="${state.method===1}">留意支撑</button></div><h2>${state.method===0?'看颜色 · 形状 · 细节':'感受椅子或地面的支撑'}</h2><p>可以睁眼，自然呼吸。<br>不舒服就停，找老师陪。</p></section></div>`}`}
const cartoonLines=[{"speaker": "小雨", "text": "今天心里有点乱。我还不想说原因。", "start": 0, "end": 4.83, "caption": "先听见朋友的感受。", "label": "说出感受"}, {"speaker": "小禾", "text": "听起来，你挺难受。没关系，我在这里。", "start": 4.83, "end": 9.042, "caption": "不用急着劝开心，也不用追问。", "label": "回应感受"}, {"speaker": "小雨", "text": "谢谢。我现在只想有人陪一会儿。", "start": 9.042, "end": 13.072, "caption": "陪伴，也是一种支持。", "label": "表达需要"}, {"speaker": "小禾", "text": "好。你想让我听一听，还是一起想办法？", "start": 13.072, "end": 17.466, "caption": "先问对方需要哪一种支持。", "label": "询问需要"}, {"speaker": "小雨", "text": "先陪我坐一会儿吧。等我想说了，再告诉你。", "start": 17.466, "end": 23.376, "caption": "尊重对方暂时不分享的选择。", "label": "尊重选择"}, {"speaker": "小禾", "text": "好。如果你需要帮助，我们也可以一起找老师。", "start": 23.376, "end": 28.455, "caption": "需要时，一起找可信任的大人。", "label": "连接帮助"}];
const cartoonDuration=29;
function cartoon(){return `<section class="cartoon-theater"><div class="cartoon-stage" id="cartoonStage"><img src="${asset('assets/library.webp')}" alt="两名同学在图书馆交流"><div class="speech-bubble" id="cartoonBubble">${cartoonLines[0].speaker}：${cartoonLines[0].text}</div><span class="cartoon-step" id="cartoonStep">1 / ${cartoonLines.length} · ${cartoonLines[0].label}</span></div><div class="cartoon-controls"><p id="cartoonCaption" aria-live="polite">${cartoonLines[0].caption}</p><div><button class="primary" id="cartoonToggle">播放有声对话</button><button id="cartoonReset">从头播放</button><span id="cartoonTime">00:00 / ${timeText(cartoonDuration)}</span></div><audio id="cartoonAudio" preload="metadata" src="${asset('media/dialogue.mp3')}"></audio><p class="fine">双角色合成配音 · 可暂停讨论</p></div></section>`}
function support(){return `${heading('朋友难过时，怎样回应？','先听见感受，再问需要。')}${cartoon()}<div class="support-mini"><span>① 回应感受</span><span>② 询问需要</span><span>③ 连接帮助</span><button id="openOriginalVideo">播放有声短片 · 45秒</button></div>`}
function stopCartoon(){clearInterval(cartoonTimer);cartoonTimer=null;cartoonRunning=false;const a=$('#cartoonAudio');if(a){cartoonElapsed=a.currentTime;a.pause()}$('#cartoonStage')?.classList.remove('playing')}
function drawCartoon(){let i=cartoonLines.findIndex(x=>cartoonElapsed<x.end);if(i<0)i=cartoonLines.length-1;const stage=$('#cartoonStage');if(!stage)return;const changed=stage.dataset.scene!==String(i);stage.dataset.scene=i;$('#cartoonBubble').textContent=cartoonLines[i].speaker+'：'+cartoonLines[i].text;$('#cartoonCaption').textContent=cartoonLines[i].caption;$('#cartoonStep').textContent=`${i+1} / ${cartoonLines.length} · ${cartoonLines[i].label}`;$('#cartoonTime').textContent=timeText($('#cartoonAudio')?.ended?cartoonDuration:Math.floor(cartoonElapsed))+' / '+timeText(cartoonDuration);$('#cartoonToggle').textContent=cartoonRunning?'暂停对话':$('#cartoonAudio')?.ended?'再听一次':cartoonElapsed?'继续对话':'播放有声对话';stage.classList.toggle('playing',cartoonRunning);if(changed){stage.classList.remove('scene-change');void stage.offsetWidth;stage.classList.add('scene-change')}}
async function toggleCartoon(reset=false){const a=$('#cartoonAudio');if(!a)return;if(reset){stopCartoon();a.currentTime=0;cartoonElapsed=0}else if(cartoonRunning){stopCartoon();drawCartoon();return}if(a.ended){a.currentTime=0;cartoonElapsed=0}a.onended=()=>{stopCartoon();drawCartoon()};a.onpause=()=>{if(cartoonRunning){stopCartoon();drawCartoon()}};try{await a.play();if(!a.isConnected){a.pause();return}cartoonRunning=true;drawCartoon();clearInterval(cartoonTimer);cartoonTimer=setInterval(()=>{cartoonElapsed=a.currentTime;drawCartoon()},100)}catch(e){stopCartoon();drawCartoon();$('#cartoonCaption').textContent='声音未能播放，请再次点击播放。'}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.practiceMode!==undefined){stopTimer();practiceMode=+b.dataset.practiceMode;render()}if(b.dataset.object!==undefined&&gameIndex<3){if(+b.dataset.object===seekOrder[gameIndex]){gameIndex++;gameMessage=gameIndex===3?'你完成了三个观察。想想刚才看到了哪些细节。':'找到了。再观察下一个。'}else gameMessage='再看看形状，也可以读物品名称。';render()}if(b.dataset.gameReset){gameIndex=0;gameMessage='';render()}if(b.id==='startVoiced'){voice=true;const box=$('#voice');if(box)box.checked=true;if(!running)toggleTimer();else syncGuide()}if(b.id==='cartoonToggle')toggleCartoon();if(b.id==='cartoonReset')toggleCartoon(true);if(b.id==='openOriginalVideo'){stopCartoon();$('#teacherContent').innerHTML=`<h2>同伴支持短片</h2><video controls playsinline style="width:100%" src="${asset('media/friend-story.mp4')}"></video><p>45秒 · 授课者授权音色合成旁白。</p>`;$('#teacherDialog').showModal()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&cartoonRunning){stopCartoon();drawCartoon()}});

const renderers=[first,signals,thoughts,regulation,grounding,action,rehearsal,support,ending];
const teacherNotes=[
 {goal:'先建立参与约定，再体验同一件事可以引起不同感受。',flow:'0—2分钟：开场与约定。\n2—5分钟：互动1。30秒读故事，30秒心里选或手势选，80秒邀请最多两位自愿者说可能的原因，40秒收尾。',script:'“你不需要真的上台。可以在心里选，或者用手指表示。今天不评选谁更会控制情绪，也不追问私人经历。”',fallback:'冷场时，老师代说小雨期待分享爱好、小安担心忘词。两种感受都说得通。投影时的点选只用于展示，不代表全班投票统计。'},
 {goal:'理解情绪相关反应及感受与行为的区别。',flow:'5—8分钟：对照身体、脑中的话、想做的事，串起小宁的例子。\n8—10分钟：讲解情绪有时提示需要，再示范安全表达。',script:'“一个身体信号不能说明一种情绪。比如心跳快，也可能是刚活动过。生气可以被理解，表达时也可以保护彼此。”',fallback:'不请学生模拟急促呼吸、愤怒或哭泣。身体明显不适时找老师或校医。理论来源：Gross（2002）、UNICEF情绪识别活动。'},
 {goal:'用认知行为模型解释联系，区分观察与推断，保留求助权利。',flow:'10—12分钟：教师切换两条理解路径，强调不是强迫乐观。\n12—15分钟：互动2。30秒读笑声情境，30秒选择，45秒解释，45秒讨论如何了解，30秒收尾。',script:'“感受是真的，对原因的解释还可以继续了解。不是所有事情都靠换想法解决；真实的排斥、嘲笑和伤害需要认真处理。”',fallback:'若有人说“那都是我想多了”，回应“不是，你的感受需要被认真对待”。真实经历转到课后单独支持，不在全班调查。此处是认知行为模型科普，不是CBT治疗。'},
 {goal:'看见情绪调节有不同入口，用口诀组织已学内容。',flow:'15—17分钟：结合例子说明五个入口，重点点击调整注意、重新理解、改变情境。\n17—19分钟：串起“看见、缓一缓、选一步”，示范从“我很差”改成“我有点失望”。',script:'“五种不是必做的五步。你可以选择适合眼前情况的入口。有些问题需要改变环境和获得帮助。”',fallback:'Gross模型用于解释策略类别，不证明某方法对所有人有效。认知改变不能用来合理化羞辱或伤害。口诀是本课教学整理，不是独立理论。'},
 {goal:'理解调整注意，实际练习一次，并能说出自己做了什么。',flow:'19—21分钟：说明物品观察与身体支撑，自然呼吸作为可选方式。\n21—26分钟：互动3。40秒说明选择，30秒准备，60秒第一轮计时，60秒安静再试，40秒回到课堂，50秒复盘，20秒收尾。',script:'“可以睁眼、可以旁观，也可以随时停下来。分心后再看回来，也是在练习。刚才你把注意力放在哪里？不用报告自己的心情。”',fallback:'不强制深呼吸、憋气、闭眼，不比较谁更放松。有人不适就停下并由成人支持。两个60秒版本均为本课原创中文合成语音，随网页内置，已留停顿。勾选同步引导后开始计时，暂停会同时暂停音频。下一站会停止媒体。语音不是治疗，也无需学生照做每一步。'},
 {goal:'把选择具体化，区分可以沟通的提醒与需要保护的情境。',flow:'26—28分钟：回扣调节入口和眼前的小行动。\n28—30分钟：事情没做好时的自我对话。\n30—32分钟：具体提醒、羞辱或威胁的不同处理。',script:'“先做什么，越具体越容易开始。你可以先休息或找人一起想，不用把每个困难都归为自己不够努力。”',fallback:'不点评真实成绩，不要求被伤害的学生独自沟通。持续羞辱、威胁或欺凌优先找成人协助。'},
 {goal:'每位愿意参与的学生说一句话并做一个小动作。',flow:'32—36分钟：互动4。30秒读情境，30秒独立想，30秒教师示范，45秒A说与B复述，45秒交换，30秒共同反馈，30秒收尾。页面4分钟计时按此切换提示。演练说明音频只替换最初的教师读题，不另加时间。',script:'“替故事里的小安试一试。可以说：我有点烦，先看笔的颜色，再圈出一道不懂的题请教老师。”',fallback:'同伴只检查具体、安全、可执行。若建议只有“加油”，老师示范具体动作。允许独立默想或写下，不收集私人经历，不给心理能力评分。'},
 {goal:'学会支持性回应，了解求助时机与可说出口的求助句。',flow:'36—38分钟：同伴支持示范。\n38—40分钟：日常迁移，方法无效时可以休息、换方法或寻求帮助。\n40—43分钟：求助时机及安全边界。\n43—45分钟：示范完整求助句。',script:'“朋友可以先听、再问，不用独自承担治疗和保护的责任。困扰不严重也可以求助，不必满足某个持续时间。”',fallback:'课前确认校内至少一位真实负责老师及联系方式。即时风险由成人陪同并启动学校支持流程，不承诺绝对保密；可能施害的家长不能自动作为披露对象。本页45秒原创中文短片内置于网页。选用时替换示范：20秒观察问题、45秒短片、35秒反馈、20秒边界，共2分钟。画面带文字，静音也可读。短片无外部播放器或登录；若设备无法解码，教师直接读同页示例。'},
 {goal:'检查能否提出具体行动，留出提问与机动时间。',flow:'45—47分钟：读小宁情境，学生心里选并想第一步，邀请最多一位回答，教师反馈与总结。\n47—50分钟：1—2个方法问题及机动。',script:'“试了还是难受，不一定是做错了。可以换方法、休息或求助。今天带走一个愿意尝试的方法就够了。”',fallback:'这是学习检查，不是测量心理健康或调节能力。前面延迟最多2分钟时压缩问答，保留结束语。私人问题不在全班分析。'}];
function promptNow(kind){if(remaining===0)return kind==='ground'?'这一轮结束。看看周围，想想刚才做了什么。':'演练结束。能说出一个具体行动，就已经开始练习了。';if(!running&&remaining===total)return kind==='ground'?'坐得舒服些，准备好时再开始。':'准备好后，读一读小安的故事。';let elapsed=total-remaining;if(kind==='ground'){const prompts=state.method===0?['选一件眼前的物品，眼睛可以睁着。','看看它的颜色，留意一处细节。','留意它的形状、边缘或纹理。','分心也没关系，愿意时再看回来。']:['坐得舒服些，感受椅子的支撑。','留意双脚与地面接触的感觉。','保持舒服的呼吸，不用刻意加深。','看看眼前的空间，按自己的节奏。'];return prompts[Math.min(3,Math.floor(elapsed/15))]}return elapsed<30?'独立想一想：我有点……我先……':elapsed<75?'同桌 A 说 30 秒，B 用 15 秒复述。':elapsed<120?'交换：B 说 30 秒，A 用 15 秒复述。':elapsed<150?'一起检查：具体、安全、现在能做吗？':'记住一个愿意尝试的小行动。'}
function stopTimer(){if(timer)clearInterval(timer);timer=null;running=false;const a=$('#guideAudio');if(a)a.pause()}
function syncGuide(){const a=$('#guideAudio');if(!a)return;if(!voice||!running){a.pause();return}a.currentTime=total-remaining;a.play().catch(()=>{const el=$('#voiceStatus');if(el)el.textContent='声音未能启动，请重新点击开始，或跟着文字练习。'})}
function updateTimer(){const clock=$('#clock');if(!clock)return;clock.textContent=timeText(remaining);$('.timer-face').style.setProperty('--sweep',((total-remaining)/total*360)+'deg');$('.practice-panel').classList.toggle('is-running',running);const kind=step===6?'pair':'ground',prompt=promptNow(kind);$('#timerPrompt').textContent=prompt;$('#timerToggle').textContent=running?'暂停练习':remaining===0?'再试一轮':remaining===total?'开始练习':'继续练习';if(prompt!==lastPrompt)lastPrompt=prompt;}
function toggleTimer(){if(running){stopTimer();updateTimer();return}if(remaining===0)remaining=total;running=true;lastPrompt='';updateTimer();syncGuide();let last=performance.now();timer=setInterval(()=>{let now=performance.now(),seconds=Math.floor((now-last)/1000);if(seconds>0){last+=seconds*1000;remaining=Math.max(0,remaining-seconds);if(remaining===0){clearInterval(timer);timer=null;running=false}updateTimer()}},200)}
const lessons=[{"title": "情绪，是我们对处境的反应。", "basis": "情绪识别与心理教育", "intro": "先有一个共同理解，再开始今天的故事。", "cards": [["感受", "开心、紧张、失望……都是可能出现的体验。"], ["信号", "身体、脑中的话、行动冲动，常常一起出现。"], ["选择", "感觉可以被理解，行动还可以再选择。"]], "example": "紧张时想躲开，并不代表你胆小；也不代表你只能躲开。", "question": "为什么同一句“明天上台”，有人期待，有人紧张？", "answer": "我们在意的事、经历和理解可能不同。感受没有统一答案，也不需要公开证明自己的感受。", "transfer": "今天只记三件事：看见感受；猜测可以核实；选择一步或找支持。", "times": [2, 2, 1]}, {"title": "情绪像提示信息，需要结合情境读。", "basis": "情绪的功能 · 非一一对应", "intro": "情绪有时提醒我们在意什么，但不能靠一个信号下结论。", "cards": [["担心", "可能提醒我们在意结果，希望有准备。"], ["生气", "可能与界限受侵犯、受挫或不公平有关。"], ["难过", "可能与失去、失望或需要陪伴有关。"]], "example": "心跳快可能与紧张、兴奋或刚运动有关。先了解当时发生了什么。", "question": "“我很生气”和“我可以推人”，是一回事吗？", "answer": "不是。承认感受，不等于认可所有行为。可以说“我不喜欢这样”，也可以离开现场找老师。", "transfer": "试着说完整：我有点……；我身体的信号是……；我可能需要……。", "times": [2, 2, 1]}, {"title": "事实之外，我们还会加上一层解释。", "basis": "认知行为模型（CBT）· 简化示意", "intro": "想法、感受与身体、行为会相互影响；实际处境也会影响它们。", "cards": [["想法", "“他没回应，是不是讨厌我？”"], ["感受与身体", "委屈、担心，身体有些紧。"], ["行为", "不再打招呼，也少了了解原因的机会。"]], "example": "换成“原因还不清楚”，是在留出核实的空间，不是要求自己认定“一切都好”。", "question": "如果脑中出现“他们肯定笑我”，下一步能问什么？", "answer": "我直接观察到了什么？原因确认了吗？还有哪些可能？如果受到伤害，可以马上求助。", "transfer": "观察：后排有人笑。推测：他们在笑我。感受：我有点受伤。三者可以分开说。", "times": [2, 2, 1]}, {"title": "调节情绪，就是寻找合适的介入点。", "basis": "Gross 情绪调节过程模型", "intro": "从事情发生的环境，到注意、解释和反应，都可能有可调整的地方。", "cards": [["环境", "选择情境、改变情境：换时间聊，或请人处理困难。"], ["注意与理解", "调整注意、重新理解：看回眼前，或核实猜测。"], ["反应", "调节反应：给身体缓冲，选择安全的表达。"]], "example": "如果是反复被欺负，仅仅调整想法不够，还需要成人介入并改变处境。", "question": "遇到难题与遇到威胁，可以只用同一种方法吗？", "answer": "不能机械套用。难题可以拆小、请教；威胁要优先保护安全、找可信任的大人。", "transfer": "五类策略不是五个必做步骤。根据情境选择，做过没帮助也可以更换。", "times": [2, 1, 1]}, {"title": "注意力可以练习“发现走神，再回来”。", "basis": "注意调节 · 参考 WHO 着陆练习", "intro": "缓冲的目的，是让我们重新留意眼前，并为下一步行动留出空间。", "cards": [["发现", "注意到：我又被担心带走了。"], ["回来", "看一件眼前的物品，留意颜色或形状。"], ["选择", "仍然紧张也没关系，再决定一个小行动。"]], "example": "不是清空脑子，也不是比谁更放松。这个圆环只显示练习进度，不规定呼吸节奏。", "question": "分心好几次，是不是说明练习失败了？", "answer": "不是。发现分心并愿意回来，就是这次练习的内容；不舒服时可以停止或请老师陪。", "transfer": "练习后问：我的注意刚才在哪里？现在愿意先做哪一步？不比较放松分数。", "times": [2, 3, 2]}, {"title": "把“解决全部”换成一个具体的小步骤。", "basis": "问题解决 · 认知与行动的联系", "intro": "有些问题可以先动一步；有些问题需要休息、支持或改变环境。", "cards": [["说清问题", "“这道题不会”，比“我什么都不行”更具体。"], ["选小步骤", "圈出卡住的地方，整理一个问题。"], ["看是否合适", "现在能做吗？安全吗？需要谁帮助？"]], "example": "“我一定要优秀”很难立刻执行；“把不会的地方问清楚”更容易开始。", "question": "怎样把“我要努力”改成能执行的一句话？", "answer": "例如：我先圈出一道不会的题，下课请教老师。重点是具体、安全、能开始。", "transfer": "行动不能保证立刻改变情绪；需要时可以先休息，或让别人陪你做。", "times": [2, 3, 1]}, {"title": "知道方法之后，还要在情境里用一次。", "basis": "技能演练 · 迁移练习", "intro": "把前面的方法接起来：说出感受，留出缓冲，选一个行动。", "cards": [["看见", "“我有点着急，卡在这里了。”"], ["缓冲", "“我先看看眼前的笔，让自己停一下。”"], ["行动", "“再把不懂的地方圈出来，请人帮忙。”"]], "example": "今天只练虚构故事。不需要表演强烈情绪，也不用讲自己的私人经历。", "question": "同桌说“我要好起来”，你可以怎样帮助他更具体？", "answer": "可以问：“你打算先做哪一小步？”复述对方的话，不评价对方心理好不好。", "transfer": "检查三个词：具体、安全、能开始。愿意时选一个带回生活。", "times": [0.5, 3, 0.5]}, {"title": "被理解和获得实际帮助，都属于支持。", "basis": "社会支持 · 倾听与求助", "intro": "陪伴不是急着说服对方开心；也包括一起找到能帮助的人。", "cards": [["听见", "“听起来，这件事让你挺难受。”"], ["询问", "“你希望我听一听，还是一起想办法？”"], ["连接帮助", "涉及伤害或安全风险，尽快找可信任的大人。"]], "example": "朋友可以陪伴，但不必独自负责解决所有问题，更不能答应隐瞒安全风险。", "question": "短片里，哪一句回应了感受，哪一句在问需要？", "answer": "先接住感受，再问对方需要什么。对方不想说时不追问；遇到安全风险及时寻求成人帮助。", "transfer": "不必等到特别严重才求助。困扰持续影响睡眠、吃饭、上课或交往时，找大人或专业人员；涉及安全马上求助。第一位没认真回应，可以再找一位。", "times": [2, 5, 2]}, {"title": "把整堂课连成一条可以使用的路线。", "basis": "课程回顾 · 三个核心观点", "intro": "不用背理论名字，能在一个日常情境里用出来更重要。", "cards": [["看见感受", "情绪有信息，感受与行为可以分开。"], ["留出空间", "想法不总等于事实，可以核实，也可以缓冲。"], ["选一步", "做具体、安全的小行动，或寻找支持。"]], "example": "明天小测很紧张：看见紧张 → 留意眼前的笔 → 圈出一个问题找老师。", "question": "如果方法试过了，还是难受，怎么办？", "answer": "不意味着你失败了。可以休息、换方法、寻求更多支持；不必独自扛住。", "transfer": "离开前，在心里补全：下次遇到……，我愿意先……；需要时我可以找……。", "times": [1, 1, 3]}];
function phaseNav(){return `<nav class="lesson-phases" aria-label="本节课堂步骤">${['先理解','试一试','一起回顾'].map((x,i)=>`<button data-phase="${i}" aria-current="${phase===i?'step':'false'}"><span>0${i+1}</span>${x}</button>`).join('')}</nav>`}
function theoryView(){const l=lessons[step];return `${eyebrow('先理解 / '+titles[step])}${heading(l.title,l.intro,l.basis)}<div class="theory-flow">${l.cards.map((c,i)=>`<article class="theory-card" style="--i:${i}"><span class="card-count">0${i+1}</span><h2>${c[0]}</h2><p>${c[1]}</p></article>`).join('')}</div>${step===2?'<p class="flow-caption">想法 ↔ 感受与身体 ↔ 行为 · 相互影响，并非单向决定</p>':''}<aside class="theory-example"><span>放进生活里</span><p>${l.example}</p></aside><p class="transition-line">接下来：${step===7?'看短片，辨认回应感受与询问需要的说法。':step===6?'用小安的故事，把三步连起来。':'用下一页的情境，看看这个知识点怎样用。'}</p>`}
function reviewView(){const l=lessons[step];return `${eyebrow('一起回顾 / 把活动变成方法')}${heading(l.question,'先在心里想一想，再对照下面的小结。')}<section class="reveal-answer"><h2 class="review-label">一起回顾</h2><div class="answer-body"><span class="label">回扣知识点 · ${l.basis}</span><h2>${l.answer}</h2><p>${l.transfer}</p></div></section><div class="review-takeaway"><span>今天的主线</span><p>看见感受 <b>→</b> 留出空间 <b>→</b> 选一步或找支持</p></div>${step===8?'<button class="source-toggle" data-sources="true">查看课程依据与延伸阅读</button><div id="finalSources"></div>':''}`}
function setPhase(n){stopCartoon();cartoonElapsed=0;if(n< -1||n>2)return;stopTimer();document.querySelectorAll('audio,video').forEach(m=>m.pause());phase=n;theoryPage=0;render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true})}
function nextPart(){if(phase<2)setPhase(phase+1);else go(step===8?0:step+1)}
function previousPart(){if(phase>0||(phase===0&&[0,2,4,7].includes(step)))setPhase(phase-1);else if(step>0){go(step-1);setPhase(2)}}
function render(){const focused=document.activeElement;const selector=focused?.dataset?Object.keys(focused.dataset).find(k=>['feeling','signal','path','fact','strategy','method','action','support','recap'].includes(k)):null;const val=selector?focused.dataset[selector]:null;$('#main').innerHTML='<div class="screen-content">'+sectionBar()+(phase===-1?sectionIntro():phaseNav()+(phase===0?(theoryPage===0?theoryView():detailedTheory()):phase===1?renderers[step]():reviewView()))+'</div>';requestAnimationFrame(fitScreen);$('#main').classList.remove('fade-in');void $('#main').offsetWidth;$('#main').classList.add('fade-in');$('#progress').innerHTML=titles.map((t,i)=>`<button class="${i===step?'current':i<step?'done':''}" aria-label="第${i+1}站：${t}" ${i===step?'aria-current="step"':''} data-go="${i}"></button>`).join('');$('#stepLabel').textContent=`${String(step+1).padStart(2,'0')} / 09 · ${titles[step]}`;$('#prev').disabled=step===0&&phase===-1;$('#next').innerHTML=phase===-1?'开始这一部分 →':phase===0?(theoryPage<theoryDetails[step].length?'继续理论 →':'进入情境 →'):phase===1?'一起回顾 →':step===8?'回到第一站':'下一站 →';if(selector){const el=$(`[data-${selector}="${val}"]`);if(el)el.focus({preventScroll:true})}}
function go(n){stopCartoon();cartoonElapsed=0;if(n<0||n>8)return;stopTimer();document.querySelectorAll('audio,video').forEach(m=>m.pause());step=n;theoryPage=0;phase=[0,2,4,7].includes(n)?-1:0;total=n===6?180:60;remaining=total;lastPrompt='';render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true})}
function openMap(){$('#mapItems').innerHTML=titles.map((t,i)=>`<button data-go="${i}"><span>${String(i+1).padStart(2,'0')}　${t}</span><small>${starts[i]}—${starts[i]+durations[i]} 分钟</small></button>`).join('');$('#mapDialog').showModal()}
function openTeacher(){const n=teacherNotes[step];$('#teacherContent').innerHTML=`<p class="big-dialog-note">第 ${step+1} 站 · ${titles[step]}<br>${starts[step]}—${starts[step]+durations[step]} 分钟，含互动与讲解。</p>${[['本节目标',n.goal],['本版分步节奏',`本部分标题页约20秒，包含在首节理论时间内，不额外增加课时。先理解 ${lessons[step].times[0]} 分钟 → 情境与活动 ${lessons[step].times[1]} 分钟 → 回顾 ${lessons[step].times[2]} 分钟。合计 ${durations[step]} 分钟。先用理论页解释，再切换情境；最后直接展示小结。对照内容全部可见，学生口头、手势或同桌讨论，不必逐项点选。`],['本节详细理论讲稿',theoryDetails[step].map(a=>a.title+'\n'+a.concept+'\n'+a.compare+'\n'+a.example+'\n'+a.apply+'\n'+a.notes+'\n依据：'+a.source).join('\n\n')||'本节以迁移和回顾为主。'],['理论讲解提示',lessons[step].basis+'\n'+lessons[step].intro+' '+lessons[step].example+'\n'+lessons[step].cards.map(c=>c[0]+'：'+c[1]).join('\n')],['活动后追问',lessons[step].question+'\n'+lessons[step].answer+'\n'+lessons[step].transfer],['可以这样说',n.script],['可选活动版本',step===4?'有声观察练习与视觉观察小游戏二选一，共占本节3分钟：说明30秒、观察约60秒、分享与回顾90秒。游戏不计分、不排名，不测量注意能力。':step===7?'30秒双人有声对话与45秒有声短片二选一，替换原示范时间，不额外加课时。可暂停，辨认回应感受、询问需要、连接帮助。':'按既定活动执行。'],['冷场、适龄与支持提示',n.fallback]].map(a=>`<div class="note-block"><h3>${a[0]}</h3><p>${a[1]}</p></div>`).join('')}<p class="teacher-source">课堂共50分钟。课堂正文已加大字号；手机自动调整排版。案例和说明直接展示，无在线投票统计。<br><a href="https://www.who.int/publications/i/item/9789240003927" target="_blank" rel="noopener noreferrer">WHO方法参考</a><a href="https://www.unicef.org/adolescentmentalhealthhub/documents/helping-adolescents-thrive-facilitator-guide" target="_blank" rel="noopener noreferrer">UNICEF教学参考</a></p>`;$('#teacherDialog').showModal()}
function handleSelection(key,i){document.querySelectorAll('audio,video').forEach(m=>m.pause());state[key]=i;if(key==='method'){stopTimer();remaining=total;lastPrompt=''}render()}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.matches('.brand')){e.preventDefault();go(0);return}if(b.dataset.close){$('#'+b.dataset.close).querySelectorAll('audio,video').forEach(m=>m.pause());$('#'+b.dataset.close).close();return}if(b.dataset.go!==undefined){document.querySelectorAll('dialog[open]').forEach(d=>d.close());go(+b.dataset.go);return}for(const key of ['feeling','signal','path','fact','strategy','method','action','support','recap'])if(b.dataset[key]!==undefined){handleSelection(key,+b.dataset[key]);return}if(b.dataset.phase!==undefined){setPhase(+b.dataset.phase);return}if(b.dataset.sources){$('#teacherContent').innerHTML=courseSources;$('#teacherContent details').open=true;$('#teacherDialog').showModal();return}if(b.id==='motionBtn'){motion=!motion;document.body.classList.toggle('still',!motion);b.textContent=motion?'动效：开':'动效：关';b.setAttribute('aria-pressed',String(motion));return}if(b.id==='prev')previousPart();if(b.id==='next')nextPart();if(b.id==='contentsBtn')openMap();if(b.id==='teacherBtn')openTeacher();if(b.id==='timerToggle')toggleTimer();if(b.id==='timerReset'){stopTimer();remaining=total;lastPrompt='';updateTimer()}if(b.id==='fullBtn'){if(!document.fullscreenElement){document.documentElement.requestFullscreen?.().catch(()=>{b.textContent='请用浏览器全屏'})}else document.exitFullscreen?.()}});
document.addEventListener('change',e=>{if(e.target.id==='voice'){voice=e.target.checked;syncGuide()}});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||e.altKey||e.ctrlKey||e.metaKey||e.target.closest('input,textarea,select,audio,video,[contenteditable=true]'))return;if(['ArrowRight','ArrowDown','PageDown'].includes(e.key)){e.preventDefault();nextPart()}if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();previousPart()}});
document.addEventListener('play',e=>{if(!e.target.matches('audio,video'))return;document.querySelectorAll('audio,video').forEach(m=>{if(m!==e.target)m.pause()});if(e.target.id!=='guideAudio'&&running){stopTimer();updateTimer()}},true);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&running){stopTimer();updateTimer()}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
lessons.forEach((l,i)=>l.times=revisedTimes[i]);
render();

function fitScreen(){const desktop=innerWidth>=900;document.body.classList.toggle('classroom-screen',desktop);const m=$('#main'),c=$('.screen-content');if(!c)return;c.style.transform='';c.style.width='';if(!desktop)return;const width=Math.min(1224,m.clientWidth-40);c.style.width=width+'px';const scale=Math.min(1,(m.clientHeight-16)/c.scrollHeight);c.style.transform=`translateX(-50%) scale(${scale})`;}
window.addEventListener('resize',()=>requestAnimationFrame(fitScreen));document.addEventListener('load',e=>{if(e.target.tagName==='IMG')requestAnimationFrame(fitScreen)},true);requestAnimationFrame(fitScreen);

function theoryView(){const v=visualLessons[step];return `${eyebrow('先理解 / '+titles[step])}<div class="visual-lesson"><section class="visual-copy"><h2 class="model-name">${theoryNames[step]}</h2><h1>${v[0]}</h1><div class="living-model ${step===2?'mutual-model':''}">${v[3].map((x,i)=>`<div class="living-node" style="--i:${i}"><span class="node-dot">${i+1}</span><div><h2>${x}</h2><p>${v[4][i]}</p></div></div>${i<2?`<span class="living-link" aria-hidden="true">${step===2?'↕':'↓'}</span>`:''}`).join('')}</div><p class="visual-bottom">${v[5]}</p></section>${sceneArt(v[1],v[2])}</div>`}
function reviewView(){const v=recapVisual[step];return `${eyebrow('一起回顾 / 这一次，记住什么')}<div class="review-poster"><section><h1>${v[0]}</h1><p>${v[1]}</p><div class="poster-route"><span>看见感受</span><b>→</b><span>留出空间</span><b>→</b><span>选一步</span></div><p class="poster-question">${['为什么会有不同感觉？','生气时，可以怎样安全表达？','你观察到了什么，又猜测了什么？','遇到难题和遇到威胁，方法一样吗？','刚才，你的注意放在哪里？','现在能做的第一步是什么？','这一步具体、安全、能开始吗？','可以向谁求助？','下次遇到……，我愿意先……。'][step]}</p></section>${sceneArt(['window.webp','homework.webp','library.webp','courtyard.webp','notebook.webp','teacher.webp','walking.webp','teacher.webp','walking.webp'][step],step===8?'带回生活里':'停一下，想一想')}</div>${step===8?'<button class="source-toggle" data-sources="true">课程依据与延伸阅读</button><div id="finalSources"></div>':''}`}

function eyebrow(label){return "";}

function phaseNav(){return `<nav class="lesson-phases" aria-label="本节课堂步骤">${['理论讲解','情境与活动','回顾与应用'].map((x,i)=>`<button data-phase="${i}" aria-current="${phase===i?'step':'false'}">${x}</button>`).join('')}</nav>`}
function openMap(){$('#mapItems').innerHTML=courseSections.map((s,i)=>`<section class="map-section"><h3><button data-go="${s.start}">0${i+1} · ${s.title}</button></h3>${titles.map((t,n)=>n>=s.start&&n<(courseSections[i+1]?.start??9)?`<button data-go="${n}"><span>${t}</span><small>${starts[n]}—${starts[n]+durations[n]} 分钟</small></button>`:'').join('')}</section>`).join('');$('#mapDialog').showModal()}

// Scenario prompts are read by the teacher; only guided practice retains audio.
function audioPlayer(name,label){return "";}

function nextPart(){if(phase===0&&theoryPage<theoryDetails[step].length){theoryPage++;render();$('#main').focus({preventScroll:true});return}if(phase<2)setPhase(phase+1);else go(step===8?0:step+1)}
function previousPart(){if(phase===0&&theoryPage>0){theoryPage--;render();$('#main').focus({preventScroll:true});return}if(phase===1){setPhase(0);theoryPage=theoryDetails[step].length;render();return}if(phase>0||(phase===0&&[0,2,4,7].includes(step)))setPhase(phase-1);else if(step>0){go(step-1);setPhase(2)}}

function markKey(text,cls){const end=text.indexOf("；")>=0?text.indexOf("；"):text.indexOf("。");const n=end>0?end:Math.min(18,text.length);return `<mark class="${cls}">${text.slice(0,n)}</mark>${text.slice(n)}`;}

// Closing the video dialog also stops its soundtrack.
$("#teacherDialog").addEventListener("close",()=>{$("#teacherDialog").querySelectorAll("audio,video").forEach(m=>m.pause())});
